ALTER TABLE public.reader_joint_participants ADD COLUMN left_at timestamptz;
CREATE OR REPLACE FUNCTION public.reader_joint_action(p_action text,p_club uuid DEFAULT NULL,p_reading uuid DEFAULT NULL,p_book uuid DEFAULT NULL,p_chapters integer DEFAULT 1,p_goal text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE b public.books; r public.reader_joint_readings; p public.reader_joint_participants; result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión.'; END IF; IF p_action='create' THEN IF NOT EXISTS(SELECT 1 FROM public.reader_clubs WHERE id=p_club AND owner_id=auth.uid()) THEN RAISE EXCEPTION 'Solo la persona propietaria.'; END IF; SELECT * INTO STRICT b FROM public.books WHERE id=p_book AND user_id=auth.uid(); INSERT INTO public.reader_joint_readings(club_id,title,author,isbn,chapters,goal) VALUES(p_club,b.title,b.author,b.isbn,p_chapters,p_goal) RETURNING id INTO result; RETURN result; END IF; SELECT * INTO STRICT r FROM public.reader_joint_readings WHERE id=p_reading; IF NOT public.reader_club_member(r.club_id,auth.uid()) THEN RAISE EXCEPTION 'No perteneces al club.'; END IF; IF p_action='leave' THEN UPDATE public.reader_joint_participants SET left_at=coalesce(left_at,now()) WHERE reading_id=r.id AND user_id=auth.uid(); RETURN r.id; END IF; IF p_action<>'join' THEN RAISE EXCEPTION 'Acción inválida.'; END IF; SELECT * INTO STRICT b FROM public.books WHERE id=p_book AND user_id=auth.uid(); IF public.reader_identity(b.title,b.author)<>public.reader_identity(r.title,r.author) AND (public.reader_isbn(b.isbn)='' OR public.reader_isbn(b.isbn)<>public.reader_isbn(r.isbn)) THEN RAISE EXCEPTION 'Elige una edición de esta lectura.'; END IF; SELECT * INTO p FROM public.reader_joint_participants WHERE reading_id=r.id AND user_id=auth.uid(); IF FOUND AND p.book_id<>b.id THEN RAISE EXCEPTION 'Esta participación conserva su edición e historial.'; END IF; INSERT INTO public.reader_joint_participants(reading_id,user_id,book_id) VALUES(r.id,auth.uid(),b.id) ON CONFLICT(reading_id,user_id) DO UPDATE SET left_at=null; RETURN r.id; END $$;
CREATE FUNCTION public.reader_close_club_participation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN UPDATE public.reader_joint_participants p SET left_at=coalesce(p.left_at,now()) FROM public.reader_joint_readings r WHERE p.reading_id=r.id AND r.club_id=OLD.club_id AND p.user_id=OLD.user_id; RETURN OLD; END $$;
CREATE TRIGGER close_club_participation BEFORE DELETE ON public.reader_club_members FOR EACH ROW EXECUTE FUNCTION public.reader_close_club_participation();
CREATE OR REPLACE FUNCTION public.reader_joint_percent(p_reading uuid,p_user uuid) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT CASE WHEN b.pages>0 THEN least(100,greatest(0,(b.current_page::numeric*100/b.pages)::integer)) ELSE 0 END FROM public.reader_joint_participants p JOIN public.reader_joint_readings r ON r.id=p.reading_id JOIN public.books b ON b.id=p.book_id AND b.user_id=p.user_id WHERE p.reading_id=p_reading AND p.user_id=p_user AND p.left_at IS NULL AND public.reader_club_member(r.club_id,auth.uid()) AND public.reader_club_member(r.club_id,p.user_id) AND NOT public.reader_blocked(p.user_id,auth.uid())$$;
CREATE OR REPLACE FUNCTION public.reader_joint_summary(p_reading uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE r public.reader_joint_readings; zone text; days date[]; streak integer:=0; cursor_day date; people jsonb; BEGIN SELECT * INTO STRICT r FROM public.reader_joint_readings WHERE id=p_reading; IF NOT public.reader_club_member(r.club_id,auth.uid()) THEN RAISE EXCEPTION 'No perteneces al club.'; END IF; SELECT timezone INTO zone FROM public.reader_clubs WHERE id=r.club_id;
WITH events AS (SELECT p.user_id,s.day FROM public.reader_joint_participants p JOIN public.reading_sessions s ON s.book_id=p.book_id WHERE p.reading_id=r.id AND s.to_page>s.from_page AND s.created_at>=p.joined_at AND (p.left_at IS NULL OR s.created_at<=p.left_at) UNION SELECT p.user_id,c.streak_day FROM public.reader_joint_participants p JOIN public.completed_readings c ON c.book_id=p.book_id WHERE p.reading_id=r.id AND c.streak_day IS NOT NULL AND c.finished_at>=p.joined_at AND (p.left_at IS NULL OR c.finished_at<=p.left_at)) SELECT array_agg(DISTINCT day) INTO days FROM events;
cursor_day:=(now() AT TIME ZONE zone)::date; IF NOT cursor_day=ANY(coalesce(days,'{}'::date[])) THEN cursor_day:=cursor_day-1; END IF; WHILE cursor_day=ANY(coalesce(days,'{}'::date[])) LOOP streak:=streak+1; cursor_day:=cursor_day-1; END LOOP;
SELECT coalesce(jsonb_agg(jsonb_build_object('handle',coalesce(sp.handle,'lector'),'percent',public.reader_joint_percent(r.id,p.user_id),'days',(SELECT count(DISTINCT d) FROM (SELECT s.day d FROM public.reading_sessions s WHERE s.book_id=p.book_id AND s.to_page>s.from_page AND s.created_at>=p.joined_at UNION SELECT c.streak_day FROM public.completed_readings c WHERE c.book_id=p.book_id AND c.streak_day IS NOT NULL AND c.finished_at>=p.joined_at) e))),'[]'::jsonb) INTO people FROM public.reader_joint_participants p LEFT JOIN public.reader_social_profiles sp ON sp.user_id=p.user_id AND public.reader_can_view(sp.user_id,sp.visibility,sp.club_id) WHERE p.reading_id=r.id AND p.left_at IS NULL AND public.reader_club_member(r.club_id,p.user_id) AND NOT public.reader_blocked(p.user_id,auth.uid()); RETURN jsonb_build_object('streak',streak,'participants',people,'my_percent',coalesce(public.reader_joint_percent(r.id,auth.uid()),0)); END $$;
REVOKE ALL ON FUNCTION public.reader_close_club_participation() FROM PUBLIC;